#include <bits/stdc++.h>using namespace std; int main() {    int t;    cin >> t;     while(t--) {        int n, k, x;        cin >> n >> k >> x;         // Original method with complex conditions        vector<int> res;        int a = k;         while(n > 0 && a >= 1) {            int diff = n - a;             // Check if we can pick 'a' without hitting forbidden value 'x'            if(diff >= 0 && (a != x && (diff % a != x || diff >= a))) {                 res.push_back(a);                n -= a;            } else {                a--; // try next smaller number            }        }         // Output result        if(n == 0) {            cout << "YES\n" << res.size() << "\n";            for(int &i : res)                cout << i << " ";            cout << "\n";        } else {            cout << "NO\n";        }    }     return 0;}